package enterfind.server.model;

/**
 * A change to one FACE_GROUPS row that a recognition run decided and the save transaction must
 * persist. The handler owns the grouping decision; this is the persistable form of its outcome, so
 * the DAO stays a dumb applier (insert when {@code isNew}, else update centroid/count).
 *
 * <p>{@code centroid} is the group's <em>final</em> state after this run's
 * faces were folded in (a run can add several faces to one group), not a delta — which is why the
 * DAO can apply it with a single insert or update.
 *
 * @param id         group id (generated by the handler for a new group; the existing id otherwise)
 * @param label      the group's label — an auto "Person N" for a new group, unchanged for an existing one
 * @param centroid   serialized running-mean L2-normalised centroid in the current model's space
 * @param modelHash  the embedding-space tag the centroid lives in
 * @param isNew      true to insert a new group, false to update an existing one
 */
public record FaceGroupMutation(String id, String label, byte[] centroid, String modelHash,
                                boolean isNew) {}
